-- Reviewed mapped water from OpenStreetMap contributors, ODbL 1.0.
-- Original extract checksums, dates, review exclusions and coverage are retained below.
-- Includes Inari, the Severn corridor, Cape Peninsula and reviewed Danish water areas.
-- Only explicit complete-survey coverage may replace the coarse inland-water mask.
-- No centreline network, user settings or photographic imagery is included.
CREATE TABLE IF NOT EXISTS rivers_bank(
    id INTEGER PRIMARY KEY, source_id INTEGER, source_type INTEGER, rings BLOB NOT NULL
);
CREATE VIRTUAL TABLE IF NOT EXISTS rivers_bank_bounds USING rtree_i32(id,min_x,max_x,min_y,max_y);
CREATE TABLE IF NOT EXISTS rivers_width(
    feature_id INTEGER PRIMARY KEY, metres REAL NOT NULL CHECK(metres>0 AND metres<=100000)
);
CREATE TABLE IF NOT EXISTS rivers_water_source(
    layer TEXT PRIMARY KEY, source TEXT NOT NULL, sha256 TEXT NOT NULL, coverage TEXT NOT NULL
);
CREATE VIRTUAL TABLE IF NOT EXISTS rivers_water_coverage USING rtree_i32(id,min_x,max_x,min_y,max_y);
CREATE TEMP TABLE mars_water_bank(
    id INTEGER PRIMARY KEY, source_id INTEGER, source_type INTEGER, rings BLOB NOT NULL,
    min_x INTEGER, max_x INTEGER, min_y INTEGER, max_y INTEGER
);
