CREATE INDEX IF NOT EXISTS rivers_bank_source ON rivers_bank(source_type,source_id);
CREATE INDEX mars_water_bank_source ON mars_water_bank(source_type,source_id);
DELETE FROM rivers_bank_bounds WHERE id IN (
    SELECT b.id FROM mars_water_bank p JOIN rivers_bank b
        ON b.source_type=p.source_type AND b.source_id=p.source_id
);
DELETE FROM rivers_bank WHERE id IN (
    SELECT b.id FROM mars_water_bank p JOIN rivers_bank b
        ON b.source_type=p.source_type AND b.source_id=p.source_id
);
CREATE TEMP TABLE mars_water_offset AS SELECT COALESCE(max(id),0) AS first_id FROM rivers_bank;
INSERT INTO rivers_bank(id,source_id,source_type,rings)
    SELECT first_id+p.id,source_id,source_type,rings FROM mars_water_bank p CROSS JOIN mars_water_offset;
INSERT INTO rivers_bank_bounds
    SELECT first_id+p.id,min_x,max_x,min_y,max_y FROM mars_water_bank p CROSS JOIN mars_water_offset;
DROP TABLE mars_water_offset;
DROP TABLE mars_water_bank;
