INSERT INTO rivers_water_source VALUES('banks:cape-peninsula','OpenStreetMap via overpass.private.coffee, retrieved 2026-10-26 / ODbL','93e05ef45d269b082e37fdd3e26bafc52819a48f6017b47db56ac67f15bc1e60','Complete mapped open-water features intersecting west=18.25 south=-34.4 east=18.65 north=-33.75; includes lakes, lagoons and reservoirs') ON CONFLICT(layer) DO UPDATE SET source=excluded.source,sha256=excluded.sha256,coverage=excluded.coverage;
INSERT INTO rivers_water_source VALUES('banks:danish-surviving-ponds','OpenStreetMap contributors via api.openstreetmap.org, retrieved 2026-10-26 / ODbL','2a556cea7db8af8ed317a407bbfcba22a1e5427184dec16bd75b04401a83af64','Individual surviving ponds: ways 902239253 at Gaardbo So and 1139175080 at Sperring So; additive mapped outlines only, no former-lake basin restoration or complete-coverage declaration') ON CONFLICT(layer) DO UPDATE SET source=excluded.source,sha256=excluded.sha256,coverage=excluded.coverage;
INSERT INTO rivers_water_source VALUES('banks:denmark-comparisons','OpenStreetMap contributors / Geofabrik Denmark 2026-10-25, ODbL; source SHA256 1a0e956ce660ab752024ed7c2fde6e665d7525e606416472dd41d0fd570b1451','31336841a98c0e827e4654f61c5e8fe31c44fbd21de6dfb24586f4146d181255','Additive mapped water intersecting Limfjord [8,56.25,10.2,57.25] and Zealand/Lolland [10.9,54.55,12.75,56.15]; existing source identities retained; excludes unsupported Ho jriis way 918043263 and degenerate sub-metre triangle way 1347689666; no complete-coverage declaration') ON CONFLICT(layer) DO UPDATE SET source=excluded.source,sha256=excluded.sha256,coverage=excluded.coverage;
INSERT INTO rivers_water_source VALUES('banks:inari','OpenStreetMap via overpass.private.coffee, retrieved 2026-10-26 / ODbL','d1391dc18700a28d5380b0dc9b02bd53b03e18fa5d16573f847f42f2b38be282','Complete mapped open-water areas intersecting west=26.65 south=68.82 east=27.15 north=68.96; whole referenced polygons and islands retained') ON CONFLICT(layer) DO UPDATE SET source=excluded.source,sha256=excluded.sha256,coverage=excluded.coverage;
INSERT INTO rivers_water_source VALUES('banks:nykobing-mors','OpenStreetMap via overpass.private.coffee, retrieved 2026-10-26 / ODbL','5204ca044341dfff1630dfd8e8464d0b8876980f45b526d1752fa63d1816da40','Mapped inland-water areas intersecting west=8.75 south=56.74 east=8.95 north=56.85; additive only, coastline and sea remain independent; excludes OSM way 918043263 after source review: drained land and proposed restoration, not confirmed permanent lake. Evidence: https://mors.dk/borger/natur-og-miljoe/natur/lavbundsprojekter-og-vaadomraader and https://www.watsonc.dk/en/referencer/teknisk-forundersogelse-vadomradeprojekt-ved-hojriis/') ON CONFLICT(layer) DO UPDATE SET source=excluded.source,sha256=excluded.sha256,coverage=excluded.coverage;
